const DEBUGLAYERS = q.get("debugLayers")==="1";   // &debugLayers=1 → live read-out of every sky/cloud layer opacity
const DEBUGMOON = q.get("debugMoon")==="1";       // &debugMoon=1 → moon layer radii/opacities + a pixel-ring across the limb
const DEBUGDAWN = q.get("debugDawn");             // DEPRECATED no-op: dawn is not a painted overlay anymore (true dawn = the physical twilight sky + Fajr marker; false dawn is not rendered). Kept only so old URLs don't error.
const DEBUGOPTIC = q.get("debugOptic");           // &debugOptic=halo|sundogs|pillar|anticrep|paraselene|lunarhalo → force the corresponding QA branch; lunar forces retain moonlight eligibility
const QA = q.get("qa")==="1";                     // &qa=1 → reset lastWxAt/lastWxTry on boot; window.qaState() is always assigned
const DEBUGMOTION = q.get("debugMotion")==="1";   // &debugMotion=1 → live motion telemetry overlay (rAF & cloud-paint rates, reduced-motion, paused, cloud/star Δ over 10s/60s, wx source, timeScale, reason)
const MOTIONFULL = (q.get("motion")||"")==="full";// &motion=full → force full animation even under OS prefers-reduced-motion. DEFAULT respects accessibility (motion reduced when the OS asks), but this gives an honest override for testing and for users who want it
// SINGLE SOURCE for the reduced-motion decision (was duplicated as _REDUCED + _RM). Evaluated LIVE so a mid-session
// OS toggle is honoured (matchMedia is cheap); &motion=full overrides. The CSS @media (prefers-reduced-motion) blocks
// read the SAME native signal, gated by the .motionfull opt-out class — one decision, consulted by both JS and CSS.
const isMotionReduced = () => !MOTIONFULL && !!(window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches);

// ---- SINGLE TEMPORAL SOURCE OF TRUTH -------------------------------------------------------------
// Ordinary loads follow Date.now(); explicit previews use simBase + realElapsed·timeScale. EVERYTHING
// visual (sun altitude, sky colour, prayer state, countdown, arc, moon) consumes the same simNow() API.
// An explicit timeScale=1 is an anchored 1× preview; >1 fast-forwards (3600 = 1s/hour). A fixed simTime=
// without timeScale= freezes the scene. Parameter presence expresses preview intent, not just its rate.
const _RAFNOW = ()=> (typeof performance!=='undefined' && performance.now) ? performance.now() : Date.now();
const _tsParam=q.get("timeScale");
let TIMESCALE = _tsParam!=null ? Math.max(0,+_tsParam||0) : (SIM.time!=null ? 0 : 1);
let ADVANCING = _tsParam!=null && TIMESCALE>0;          // a running fast-forward → show the sim clock
let FOLLOW_WALL_CLOCK = _tsParam==null && SIM.time==null && TIMESCALE===1;
let _clockPreview=false; // explicit runtime clock control retains forecast provenance while paused

// Nothing here is keyed to a prayer NAME. paint(A) below is the ONLY place this state touches the DOM.
// Lunar body presence/light uses accepted celestial inputs, independently of
// timetable acquisition. Both initial and ordinary paint consume these SAME
// expressions; a pending prayer request grants neither a phase nor moonlight.
function nativeLunarPresentation(moon,solarElevation,surfaceFailed){
  const mFrac=clamp(moon.frac),moonUp=clamp((moon.alt+2)/6);
  const darkness=clamp(-(solarElevation+3)/9),phaseVis=clamp((mFrac-0.02)/0.05);
  const moonObject=surfaceFailed?0:moonUp*darkness*phaseVis;
  const moonLightEligible=moonObject>0;
  const moonLightReason=surfaceFailed?"surface-unavailable":darkness===0?"daylight":moonUp===0?"below-horizon":phaseVis===0?"near-new":"eligible";
  const moonLocalWash=moonLightEligible?clamp(mFrac*moonUp*1.15):0;
  const moonGlow=moonLightEligible?(0.03+0.24*mFrac*mFrac):0;
  const moonlight=moonObject*(0.35+0.65*mFrac),moonShow=clamp(darkness*1.8);
  return {mFrac,moonUp,darkness,phaseVis,moonObject,moonLightEligible,moonLightReason,moonLocalWash,moonGlow,moonlight,moonStrength:moonlight,moonShow,moonPresence:moonShow};
}
function lunarPresentation(solarElevation){ return nativeLunarPresentation(moonSky,solarElevation,_pbrFailed); }

const belt=Math.max(0,1-Math.abs(sm.altDeg+4)/5)*((cls==="clear"||cls==="cloud")?1:0);
const skyL=skyLum(sm.altDeg);
// DAWN. (See the authoritative note just below `dep` for the true-dawn / false-dawn policy.)
const dep=-sm.altDeg, morning=M.nowMin<M.noon, clearish=(cls==="clear"||cls==="cloud"||cls==="fog");
// TRUE DAWN is the physical twilight sky (the gradient/glow above) + the Fajr marker — NOT painted. `trueDawn`
// is kept ONLY as a 0..1 DIAGNOSTIC scalar (qaState), never rendered. FALSE DAWN (zodiacal light) is NOT rendered
// at all (fail-closed): a generic CSS cone read as a decorative lens-flare slash and showed under a bright moon.
// A faithful zodiacal cue is FUTURE WORK (needs real ecliptic-tilt projection + strict dark-sky/no-moon/low-LP/
// clear-sky gating + very faint, no foreground-crossing streak, never implying Fajr). See DESIGN.md.
const trueDawn = (morning&&clearish) ? clamp((17.5-dep)/3.0)*clamp(dep/1.5) : 0;
// — cloud LAYERS (low/mid/high): prefer the real forecast layering; else split total coverage by condition.
//   low = horizon deck (thick band), mid = broad deck, high = thin upper veil. Coverage is DATA-driven, so a
//   clear sky shows NO cloud body and overcast fills the deck — not a blanket texture keyed to a data-fx name.
let clLow,clMid,clHigh;
if(current && current.cloudLow!=null){ clLow=clamp(current.cloudLow/100); clMid=clamp(current.cloudMid/100); clHigh=clamp(current.cloudHigh/100); }
else { const sp=({clear:[0,0,0],cloud:[.2,.55,.4],overcast:[.92,.85,.5],fog:[1,.2,0],drizzle:[.72,.6,.2],rain:[.9,.85,.3],thunder:[.92,.9,.6],snow:[.82,.7,.3]})[cls]||[0,0,0]; clLow=sp[0]; clMid=sp[1]; clHigh=sp[2]; }
// LUNAR OPTICS — two DISTINCT phenomena gated by cloud TYPE: a 22° ICE-crystal HALO ring from thin CIRRUS (high
// cloud), and a water-droplet CORONA aureole from thin ALTOSTRATUS/FOG. Dew point or humidity alone
// does not establish a droplet column: a humid clear scene must not grow a smooth veil over Earthshine. Both need a bright
// above-horizon moon in a dark sky; thick low cloud kills both. They are near-exclusive (ice vs water cloud).
const moonLume=moonLightEligible?moonUp*darkness*clamp(0.25+0.75*mFrac):0;
let lunarHalo    =clamp((clHigh-0.06)/0.34)*clamp((0.66-clHigh)/0.42)*(1-clLow)*(1-0.7*clMid)*moonLume;   // `let`: forceable via &debugOptic=lunarhalo
const lunarCorona=clamp(Math.max((clMid-0.08)/0.36,(cls==="fog"?0.7:0)))*clamp((0.72-clMid)/0.5)*(1-0.45*clLow)*moonLume;
// — crepuscular rays (light shafts): only when the sun is up, the deck is BROKEN (gaps to shine through),
//   and there's participating medium (humidity/haze). Clear dry sky → 0; solid overcast → directional≈0 → 0.
const broken=clamp(1-Math.abs(clMid-0.45)/0.42);                 // peaks at half-cover (gaps); 0 at clear & solid
const ray=Math.min(0.5, clamp(sm.altDeg/8)*broken*(1-0.8*clLow)*clamp(0.3+0.7*D.humid)*directional*(cls==="fog"?0.25:1));
// ICE-CRYSTAL & RAY OPTICS — all CONDITION-GATED (never random). Thin CIRRUS (high cloud, no thick low/mid) →
// 22° HALO + SUNDOGS; cold air + a low sun → SUN PILLAR; broken cloud/haze + low sun → ANTICREPUSCULAR rays
// (the faint mirror of the crepuscular `ray`). Forced individually by &debugOptic= for inspection.
const cirrus=clamp((clHigh-0.06)/0.34)*clamp((0.72-clHigh)/0.42)*(1-clLow)*(1-0.55*clMid), sunUpO=clamp((sm.altDeg+1)/6);
let sunHalo=cirrus*sunUpO, sunDogs=cirrus*sunUpO*clamp((12-sm.altDeg)/12), sunPillar=D.cold*clamp((6-sm.altDeg)/8)*clamp((sm.altDeg+5)/7)*(0.45+0.55*cirrus), antiCrep=ray*0.5;
// LUNAR PARASELENAE / moondogs: the lunar analogue of sundogs — lateral spots at the moon's elevation, RARE,
// needing a bright moon + thin ice cloud (cirrus). Lateral only when plausible.
let moonParhelia=cirrus*moonLume*clamp((14-moonSky.alt)/16);
if(DEBUGOPTIC==="halo")sunHalo=0.95; else if(DEBUGOPTIC==="sundogs")sunDogs=0.95; else if(DEBUGOPTIC==="pillar")sunPillar=0.9; else if(DEBUGOPTIC==="anticrep")antiCrep=0.8; else if(DEBUGOPTIC==="paraselene")moonParhelia=moonLightEligible?0.9:0; else if(DEBUGOPTIC==="lunarhalo")lunarHalo=moonLightEligible?0.95:0;

const _motHist=[];
function _cloudAlphaNow(){ try{ const cv=document.querySelector('.cloudcanvas'),x=cv.getContext('2d'),d=x.getImageData(0,0,cv.width,cv.height).data; let a=0; for(let i=3;i<d.length;i+=4)a+=d[i]; return a; }catch(e){ return 0; } }
function _starSampleNow(){ const els=document.querySelectorAll('.stars circle'); for(const e of els){ if(e.style.display!=='none' && getComputedStyle(e).animationName==='tw') return +getComputedStyle(e).opacity; } return 0; }   // sample a VISIBLE twinkling star (not a display:none pool star) so starΔ is representative
function updateMotionDbg(rafPS, cloudPS, cEl){
  const dm=document.querySelector('.dbgmotion'); if(!dm) return; if(dm.style.display!=='block') dm.style.display='block';
  _motHist.push({a:_cloudAlphaNow(), s:_starSampleNow()}); if(_motHist.length>61)_motHist.shift();
  const cur=_motHist[_motHist.length-1], h10=_motHist[Math.max(0,_motHist.length-11)], h60=_motHist[0];
  const pct=(a,b)=> b? (Math.abs(a-b)/b*100):0;
  const starAnim=(()=>{ const e=document.querySelector('.stars circle'); return e?getComputedStyle(e).animationName==='tw':false; })();
  const wt=(()=>{try{return qaState().wxTruth;}catch(e){return {};}})(); const rm=isMotionReduced();   // LIVE (honours a mid-session OS toggle)
  dm.textContent=`MOTION rAF ${rafPS}/s  cloudPaint ${cloudPS}/s\n`
    +`reduced ${rm?'YES':'no'}  motion=full ${MOTIONFULL?'YES':'no'}  paused ${cEl.classList.contains('paused')?'YES':'no'}\n`
    +`timeScale ${TIMESCALE}  advancing ${ADVANCING?'yes':'no'}\n`
    +`cloudΔ 10s ${pct(cur.a,h10&&h10.a).toFixed(1)}%  60s ${pct(cur.a,h60&&h60.a).toFixed(1)}%\n`
    +`starΔ 10s ${(cur.s-(h10?h10.s:cur.s)).toFixed(3)}  starAnim ${starAnim?'on':'OFF'}\n`
    +`wx ${wt.currentWeatherSource||'?'}  fx ${cEl.dataset.fx||'?'}\n`

// (wind/precip-driven), independent of this clock. Stops entirely when the iframe is hidden/offscreen.
function startRenderLoop(){
  if(!simulationReady()) return;
  if(_loopStarted) return; _loopStarted=true;
  const cEl=document.querySelector(".c");
  if(MOTIONFULL && cEl) cEl.classList.add("motionfull");    // CSS reduced-motion rules are scoped to .c:not(.motionfull)
  let _raf=null, _onScreen=true, _lastSec=-1, _lastWx=0, _lastCloud=0;
  const visible=()=>_onScreen && document.visibilityState!=="hidden";
  // —— MOTION TELEMETRY (&debugMotion=1): prove the sky is actually alive in normal real-time ——
  let _rafN=0,_cloudN=0,_tickAcc=_RAFNOW(),_rafPS=0,_cloudPS=0;   // loop rate counters (consumed only by the debugMotion overlay, which now lives at module scope)
  function loop(){
    _rafN++;
    if(!simulationReady()){ _raf=requestAnimationFrame(loop); return; }
    const n=nowParts();
    maintainPrayerDay();                               // promotion, rollover and cold same-day recovery share this visible opportunity
    const rt=_RAFNOW();
    if(!ADVANCING && rt-_lastWx>30000){ _lastWx=rt; fetchWeather(); fetchRadar(); }    // refresh real weather ~½-min + radar (self-throttled ~10min); both held during a fast sweep
    const sec=Math.floor(simNow()/1000);
    if(sec!==_lastSec || _renderDirty){ _lastSec=sec; _renderDirty=false; render(); if(ADVANCING) updateSimClock(n); }
    // Cloud evolution uses bounded visual intervals, with CLOCK's preview rate. Reduced-motion
    // paints changed state at the same held axes, never a substitute epoch like 1000.
    const reduced=isMotionReduced(); syncCloudMotionPreference(reduced,rt);
    if(reduced){ if(_cloudDirty){ paintClouds(simNow()/1000); tieRainToClouds(); _cloudN++; } }
    else if(rt-_lastCloud>76){ _lastCloud=rt; paintClouds(simNow()/1000); tieRainToClouds(); _cloudN++; }
    if(rt-_tickAcc>=1000){ _rafPS=Math.round(_rafN*1000/(rt-_tickAcc)); _cloudPS=Math.round(_cloudN*1000/(rt-_tickAcc)); _rafN=0;_cloudN=0;_tickAcc=rt; if(DEBUGMOTION) updateMotionDbg(_rafPS,_cloudPS,cEl); }
